(()=>{'use strict';
const launch=document.createElement('button');launch.id='aiLaunch';launch.type='button';launch.innerHTML='<span aria-hidden="true">✦</span><span>Помощник</span>';launch.setAttribute('aria-label','Открыть ИИ-помощника');launch.setAttribute('aria-haspopup','dialog');launch.setAttribute('aria-controls','aiDialog');document.body.append(launch);
const dialog=document.createElement('dialog');dialog.id='aiDialog';dialog.setAttribute('aria-labelledby','aiTitle');dialog.innerHTML='<div class="ai-head"><div><h2 id="aiTitle">Помощник Матклуба</h2><span>Объясняем, думаем, проверяем</span></div><div class="ai-head-tools"><button id="aiRead" type="button" aria-pressed="false" title="Режим чтения">Читать</button><button id="aiExpand" type="button" aria-pressed="false" title="Развернуть окно">⛶</button><button id="aiClose" type="button" aria-label="Закрыть помощника">×</button></div></div><p class="ai-note">ИИ может ошибаться. Проверяй вычисления и сопоставляй ответ с учебным разбором.</p><div id="aiMessages" role="log" aria-live="polite" aria-label="Переписка с помощником"><p class="ai-welcome">Привет! Могу объяснить тему, подсказать идею решения или помочь разобраться в коде.</p></div><div class="ai-suggestions"><button type="button" data-ai-prompt="Дай первую подсказку к открытой задаче, не раскрывая ответ.">Подскажи идею</button><button type="button" data-ai-prompt="Объясни открытую тему простыми словами и приведи пример.">Объясни тему</button></div><form id="aiForm"><details class="ai-context-details"><summary>Контекст вопроса</summary><label class="ai-context"><input id="aiContext" type="checkbox" checked> Приложить открытую задачу или тему</label><p id="aiContextLabel"></p></details><label class="ai-input-label" for="aiInput">Твой вопрос</label><textarea id="aiInput" rows="2" maxlength="2000" placeholder="Что осталось непонятным?" required></textarea><div class="ai-actions"><button type="button" id="aiClear">Очистить</button><button type="button" id="aiStop" hidden>Остановить</button><button type="submit" id="aiSend">Отправить ↗</button></div></form><button id="aiReturn" type="button" hidden>Задать следующий вопрос ↓</button><p id="aiStatus" role="status"></p><p class="ai-footer">История хранится до обновления страницы. В запрос входят сообщения чата и выбранное условие.</p>';document.body.append(dialog);
const $=s=>dialog.querySelector(s);let history=[],controller=null,busy=false;
function context(){let text='';const opened=document.querySelector('.workspace-dialog[open]');if(opened&&typeof activeTask!=='undefined'&&activeTask){text=`${activeTask.domain==='physics'?'Физика':'Математика'}, ${activeTask.grade} класс. ${activeTask.title}\n${activeTask.question}`}else if(document.querySelector('#computingSection')?.hidden===false){if(!document.querySelector('#cppPanel')?.hidden){const l=window.matclubCppCourse?.lessons.find(l=>l.id===window.matclubCpp?.state.id);if(l)text='C++: '+l.title+'\n'+l.task}else{text='Python: '+(document.querySelector('#pyLessonTitle')?.textContent||'')+'\n'+(document.querySelector('.py-exercise-head')?.textContent||'')}}else if(document.querySelector('#labSection')?.hidden===false){const e=window.matclubLabModels?.labs.find(e=>e.id===window.matclubLab?.state.id);if(e)text='Физическая лаборатория: '+e.title+'\n'+e.intro+'\n'+e.formula}else{const lesson=document.querySelector('.lesson-dialog[open]');if(lesson)text=lesson.querySelector('h2')?.textContent+'\n'+(lesson.querySelector('.lesson-intro')?.textContent||'')}return text.slice(0,3000)}
function describe(){const c=context();$('#aiContextLabel').textContent=$('#aiContext').checked?(c?'Контекст: '+c.split('\n')[0]:'Открытая задача не выбрана — можно задать любой учебный вопрос.'):'Контекст не прикладывается.'}
function formatted(target,text){
 const lines=text.split('\n');let pre=null,list=null;
 for(const line of lines){
  if(line.trim().startsWith('```')){list=null;if(pre){pre=null}else{pre=document.createElement('pre');pre.tabIndex=0;const code=document.createElement('code');pre.append(code);target.append(pre)}continue}
  if(pre){pre.firstChild.textContent+=line+'\n';continue}
  if(!line.trim()){list=null;continue}
  const item=line.match(/^\s*(?:[-*]|\d+[.)])\s+(.+)$/),heading=line.match(/^#{1,4}\s+(.+)$/);let el;
  if(item){const number=line.match(/^\s*(\d+)[.)]/),tag=number?'ol':'ul';if(!list||list.tagName.toLowerCase()!==tag){list=document.createElement(tag);if(number)list.start=Math.min(10000,Number(number[1]));target.append(list)}el=document.createElement('li');list.append(el)}else{list=null;el=document.createElement(heading?'h3':'p');target.append(el)}
  const content=item?item[1]:heading?heading[1]:line;
  for(const part of content.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)){if(part.startsWith('**')&&part.endsWith('**')){const bold=document.createElement('strong');bold.textContent=part.slice(2,-2);el.append(bold)}else if(part.startsWith('`')&&part.endsWith('`')){const code=document.createElement('code');code.textContent=part.slice(1,-1);el.append(code)}else el.append(document.createTextNode(part))}
 }
}
function bubble(role,text){const div=document.createElement('div');div.className='ai-message ai-'+role;const label=document.createElement('b');label.textContent=role==='user'?'Ты':'Помощник';const p=document.createElement('div');p.className='ai-prose';if(role==='assistant')formatted(p,text);else p.textContent=text;div.append(label,p);
 if(role==='assistant'){const tools=document.createElement('div');tools.className='ai-message-tools';const copy=document.createElement('button');copy.type='button';copy.textContent='Копировать ответ';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);$('#aiStatus').textContent='Ответ скопирован.'}catch{const range=document.createRange();range.selectNodeContents(p);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);$('#aiStatus').textContent='Ответ выделен — выбери «Копировать».'}});tools.append(copy);div.append(tools)}
 const area=$('#aiMessages');area.append(div);if(role==='assistant'){area.scrollTop+=div.getBoundingClientRect().top-area.getBoundingClientRect().top-14;dialog.classList.add('ai-has-answer')}else area.scrollTop=area.scrollHeight;return div}
function setBusy(value){busy=value;$('#aiSend').disabled=value;$('#aiStop').hidden=!value;$('#aiClear').disabled=value;$('#aiInput').readOnly=value;dialog.setAttribute('aria-busy',String(value))}
async function send(event){event.preventDefault();if(busy)return;const message=$('#aiInput').value.trim();if(!message)return;if(innerWidth<=767)$('#aiInput').blur();dialog.classList.add('ai-started');const ctx=$('#aiContext').checked?context():'';const node=bubble('user',message);setBusy(true);$('#aiStatus').textContent='Помощник думает…';controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),30000);try{const response=await fetch('/api/assistant',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({message,context:ctx,history:history.slice(-8)}),signal:controller.signal});let data;try{data=await response.json()}catch{throw Error('Сервис помощника пока недоступен.')}if(!response.ok){const wait=Number(response.headers?.get?.('retry-after'));throw Error((data.error||'Не удалось получить ответ.')+(Number.isFinite(wait)&&wait>0?' Повтори примерно через '+(wait>=3600?Math.ceil(wait/3600)+' ч.':Math.ceil(wait/60)+' мин.') :''));}if(typeof data.answer!=='string')throw Error('Модель вернула пустой ответ.');bubble('assistant',data.answer);history.push({role:'user',content:message},{role:'assistant',content:data.answer.slice(0,2000)});history=history.slice(-8);$('#aiInput').value='';$('#aiStatus').textContent='Ответ готов.'+(data.modelLabel?' · '+data.modelLabel:'')}catch(e){node.classList.add('ai-unsent');$('#aiStatus').textContent=e.name==='AbortError'?'Запрос остановлен. Вопрос сохранён в поле ввода.':e.message}finally{clearTimeout(timeout);controller=null;setBusy(false)}}
function host(){if(dialog.open)return;const others=[...document.querySelectorAll('dialog[open]')].filter(d=>d!==dialog);const target=others.at(-1)||document.body;if(launch.parentNode!==target)target.append(launch)}
new MutationObserver(host).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
launch.addEventListener('click',()=>{describe();if(!dialog.open){if(window.innerWidth<=767||document.querySelector('dialog[open]:not(#aiDialog)'))dialog.showModal();else dialog.show()}if(innerWidth>767)$('#aiInput').focus()});$('#aiClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{host();launch.focus()});dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();dialog.close()}});$('#aiForm').addEventListener('submit',send);$('#aiContext').addEventListener('change',describe);$('#aiStop').addEventListener('click',()=>controller?.abort());$('#aiClear').addEventListener('click',()=>{if(history.length&&!confirm('Очистить переписку с помощником?'))return;history=[];dialog.classList.remove('ai-has-answer','ai-started');$('#aiMessages').replaceChildren();$('#aiStatus').textContent='Переписка очищена.'});dialog.querySelectorAll('[data-ai-prompt]').forEach(b=>b.addEventListener('click',()=>{$('#aiInput').value=b.dataset.aiPrompt;describe();$('#aiInput').focus()}));function reading(on){dialog.classList.toggle('ai-reading',on);$('#aiRead').setAttribute('aria-pressed',String(on));$('#aiRead').textContent=on?'К чату':'Читать';$('#aiReturn').hidden=!on}
$('#aiRead').addEventListener('click',()=>reading(!dialog.classList.contains('ai-reading')));$('#aiReturn').addEventListener('click',()=>{reading(false);$('#aiInput').focus()});$('#aiExpand').addEventListener('click',()=>{const on=dialog.classList.toggle('ai-expanded');$('#aiExpand').setAttribute('aria-pressed',String(on));$('#aiExpand').title=on?'Уменьшить окно':'Развернуть окно'});
$('#aiInput').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();$('#aiForm').requestSubmit()}});
function viewport(){if(innerWidth<=767&&window.visualViewport){dialog.style.setProperty('--ai-vh',window.visualViewport.height+'px');dialog.style.setProperty('--ai-vtop',window.visualViewport.offsetTop+'px')}else{dialog.style.removeProperty('--ai-vh');dialog.style.removeProperty('--ai-vtop')}}window.visualViewport?.addEventListener('resize',viewport);window.visualViewport?.addEventListener('scroll',viewport);window.addEventListener('resize',viewport);dialog.addEventListener('toggle',viewport);viewport();
window.addEventListener('pagehide',()=>controller?.abort());
})();
